CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, started_at INTEGER, ended_at INTEGER, summary TEXT);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, session_id TEXT, name TEXT, ip TEXT, user_agent TEXT, device_json TEXT, joined_at INTEGER, last_seen_at INTEGER, hidden_count INTEGER DEFAULT 0, was_ghost INTEGER DEFAULT 0, was_victim INTEGER DEFAULT 0, consent INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT, user_id TEXT, type TEXT, payload_json TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, session_id TEXT, user_id TEXT, text TEXT, state TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS votes (session_id TEXT, voter_id TEXT, target_id TEXT, at INTEGER, PRIMARY KEY (session_id, voter_id));
CREATE TABLE IF NOT EXISTS pacts (id TEXT PRIMARY KEY, session_id TEXT, user_id TEXT, clauses_json TEXT, penalties INTEGER, signed_at INTEGER, signature_png TEXT);
CREATE TABLE IF NOT EXISTS offerings (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT, user_id TEXT, kind TEXT, points INTEGER, at INTEGER);
CREATE TABLE IF NOT EXISTS ai_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT, pedido TEXT, prompt_json TEXT, response_json TEXT, ok INTEGER, latency_ms INTEGER, fallback INTEGER, at INTEGER);
CREATE TABLE IF NOT EXISTS snapshots (session_id TEXT PRIMARY KEY, state_json TEXT, at INTEGER);
CREATE INDEX IF NOT EXISTS idx_events_session_at ON events(session_id, at);
CREATE INDEX IF NOT EXISTS idx_questions_session_state ON questions(session_id, state);
CREATE INDEX IF NOT EXISTS idx_ai_logs_session_at ON ai_logs(session_id, at);